import{c as e,Q as o,j as t,m as l}from"./chunks/framework.CHJbb1iY.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"aside":"right","outline":[2,3]},"headers":[],"relativePath":"docs/算法/左程云/5. 时间复杂度.md","filePath":"docs/算法/左程云/5. 时间复杂度.md"}'),r={name:"docs/算法/左程云/5. 时间复杂度.md"};function i(h,a,n,d,c,s){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 style="text-align:center;font-weight:bold;">时间复杂度</h1><hr><h2 id="课程链接" tabindex="-1">课程链接 <a class="header-anchor" href="#课程链接" aria-label="Permalink to &quot;课程链接&quot;">​</a></h2><blockquote><h4 id="https-www-bilibili-com-video-bv1jv411g7de" tabindex="-1"><a href="https://www.bilibili.com/video/BV1JV411G7De" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1JV411G7De</a> <a class="header-anchor" href="#https-www-bilibili-com-video-bv1jv411g7de" aria-label="Permalink to &quot;https://www.bilibili.com/video/BV1JV411G7De&quot;">​</a></h4></blockquote><h2 id="课程笔记" tabindex="-1">课程笔记 <a class="header-anchor" href="#课程笔记" aria-label="Permalink to &quot;课程笔记&quot;">​</a></h2><h4 id="_1-常数操作-固定时间的操作-执行时间和数据量无关" tabindex="-1">（1）常数操作，固定时间的操作，执行时间和数据量无关 <a class="header-anchor" href="#_1-常数操作-固定时间的操作-执行时间和数据量无关" aria-label="Permalink to &quot;（1）常数操作，固定时间的操作，执行时间和数据量无关&quot;">​</a></h4><h4 id="_2-时间复杂度-一个和数据量有关、只要高阶项、不要低阶项、不要常数项的操作次数表达式" tabindex="-1">（2）时间复杂度，一个和数据量有关、只要高阶项、不要低阶项、不要常数项的操作次数表达式 <a class="header-anchor" href="#_2-时间复杂度-一个和数据量有关、只要高阶项、不要低阶项、不要常数项的操作次数表达式" aria-label="Permalink to &quot;（2）时间复杂度，一个和数据量有关、只要高阶项、不要低阶项、不要常数项的操作次数表达式&quot;">​</a></h4><blockquote><h4 id="举例-选择、冒泡、插入" tabindex="-1">举例：选择、冒泡、插入 <a class="header-anchor" href="#举例-选择、冒泡、插入" aria-label="Permalink to &quot;举例：选择、冒泡、插入&quot;">​</a></h4></blockquote><h4 id="_3-严格固定流程的算法-一定强调最差情况-比如插入排序" tabindex="-1">（3）严格固定流程的算法，一定强调最差情况！比如插入排序 <a class="header-anchor" href="#_3-严格固定流程的算法-一定强调最差情况-比如插入排序" aria-label="Permalink to &quot;（3）严格固定流程的算法，一定强调最差情况！比如插入排序&quot;">​</a></h4><h4 id="_4-算法流程上利用随机行为作为重要部分的-要看平均或者期望的时间复杂度-因为最差的时间复杂度无意义" tabindex="-1">（4）算法流程上利用随机行为作为重要部分的，要看平均或者期望的时间复杂度，因为最差的时间复杂度无意义 <a class="header-anchor" href="#_4-算法流程上利用随机行为作为重要部分的-要看平均或者期望的时间复杂度-因为最差的时间复杂度无意义" aria-label="Permalink to &quot;（4）算法流程上利用随机行为作为重要部分的，要看平均或者期望的时间复杂度，因为最差的时间复杂度无意义&quot;">​</a></h4><h4 id="_5-算法流程上利用随机行为作为重要部分的-还要看平均或者期望的时间复杂度-因为最差的时间复杂度无意义" tabindex="-1">（5）算法流程上利用随机行为作为重要部分的，还要看平均或者期望的时间复杂度，因为最差的时间复杂度无意义 <a class="header-anchor" href="#_5-算法流程上利用随机行为作为重要部分的-还要看平均或者期望的时间复杂度-因为最差的时间复杂度无意义" aria-label="Permalink to &quot;（5）算法流程上利用随机行为作为重要部分的，还要看平均或者期望的时间复杂度，因为最差的时间复杂度无意义&quot;">​</a></h4><blockquote><h4 id="算法流程上利用随机行为作为重要部分的-还有随机快速排序-【必备】课-、跳表-【扩展】课-也只在乎平均或者期望的时间复杂度-因为最差的时间复杂度无意义" tabindex="-1">算法流程上利用随机行为作为重要部分的，还有随机快速排序（【必备】课）、跳表（【扩展】课）也只在乎平均或者期望的时间复杂度，因为最差的时间复杂度无意义 <a class="header-anchor" href="#算法流程上利用随机行为作为重要部分的-还有随机快速排序-【必备】课-、跳表-【扩展】课-也只在乎平均或者期望的时间复杂度-因为最差的时间复杂度无意义" aria-label="Permalink to &quot;算法流程上利用随机行为作为重要部分的，还有随机快速排序（【必备】课）、跳表（【扩展】课）也只在乎平均或者期望的时间复杂度，因为最差的时间复杂度无意义&quot;">​</a></h4></blockquote><h4 id="_6-时间复杂度的内涵-描述算法运行时间和数据量大小的关系-而且当数据量很大很大时-这种关系相当的本质-并且排除了低阶项、常数时间的干扰" tabindex="-1">（6）时间复杂度的内涵：描述算法运行时间和数据量大小的关系，而且当数据量很大很大时，这种关系相当的本质，并且排除了低阶项、常数时间的干扰 <a class="header-anchor" href="#_6-时间复杂度的内涵-描述算法运行时间和数据量大小的关系-而且当数据量很大很大时-这种关系相当的本质-并且排除了低阶项、常数时间的干扰" aria-label="Permalink to &quot;（6）时间复杂度的内涵：描述算法运行时间和数据量大小的关系，而且当数据量很大很大时，这种关系相当的本质，并且排除了低阶项、常数时间的干扰&quot;">​</a></h4><h4 id="_7-空间复杂度-强调额外空间-常数项时间-放弃理论分析、选择用实验来确定-因为不同常数操作的时间不同" tabindex="-1">（7）空间复杂度，强调额外空间；常数项时间，放弃理论分析、选择用实验来确定，因为不同常数操作的时间不同 <a class="header-anchor" href="#_7-空间复杂度-强调额外空间-常数项时间-放弃理论分析、选择用实验来确定-因为不同常数操作的时间不同" aria-label="Permalink to &quot;（7）空间复杂度，强调额外空间；常数项时间，放弃理论分析、选择用实验来确定，因为不同常数操作的时间不同&quot;">​</a></h4><h4 id="_8-什么叫最优解-先满足时间复杂度最优-然后尽量少用空间的解" tabindex="-1">（8）什么叫最优解：先满足时间复杂度最优，然后尽量少用空间的解 <a class="header-anchor" href="#_8-什么叫最优解-先满足时间复杂度最优-然后尽量少用空间的解" aria-label="Permalink to &quot;（8）什么叫最优解：先满足时间复杂度最优，然后尽量少用空间的解&quot;">​</a></h4><h4 id="_9-时间复杂度的均摊-用动态数组的扩容来说明-等比数列、均摊的意义" tabindex="-1">（9）时间复杂度的均摊，用动态数组的扩容来说明（等比数列、均摊的意义） <a class="header-anchor" href="#_9-时间复杂度的均摊-用动态数组的扩容来说明-等比数列、均摊的意义" aria-label="Permalink to &quot;（9）时间复杂度的均摊，用动态数组的扩容来说明（等比数列、均摊的意义）&quot;">​</a></h4><blockquote><h4 id="并查集、单调队列、单调栈、哈希表等结构-均有这个概念。这些内容【必备】课都会讲" tabindex="-1">并查集、单调队列、单调栈、哈希表等结构，均有这个概念。这些内容【必备】课都会讲 <a class="header-anchor" href="#并查集、单调队列、单调栈、哈希表等结构-均有这个概念。这些内容【必备】课都会讲" aria-label="Permalink to &quot;并查集、单调队列、单调栈、哈希表等结构，均有这个概念。这些内容【必备】课都会讲&quot;">​</a></h4></blockquote><h4 id="_10-不要用代码结构来判断时间复杂度-比如只有一个-while-循环的冒泡排序-其实时间复杂度-o-n2" tabindex="-1">（10）不要用代码结构来判断时间复杂度，比如只有一个 while 循环的冒泡排序，其实时间复杂度 O(N²) <a class="header-anchor" href="#_10-不要用代码结构来判断时间复杂度-比如只有一个-while-循环的冒泡排序-其实时间复杂度-o-n2" aria-label="Permalink to &quot;（10）不要用代码结构来判断时间复杂度，比如只有一个 while 循环的冒泡排序，其实时间复杂度 O(N²)&quot;">​</a></h4><h4 id="_11-不要用代码结构来判断时间复杂度-比如-n-1-n-2-n-3-n-n-这个流程的时间复杂度是-o-n-logn-著名的调和级数" tabindex="-1">（11）不要用代码结构来判断时间复杂度，比如：N/1 + N/2 + N/3 + … + N/N，这个流程的时间复杂度是 O(N * logN)，著名的调和级数 <a class="header-anchor" href="#_11-不要用代码结构来判断时间复杂度-比如-n-1-n-2-n-3-n-n-这个流程的时间复杂度是-o-n-logn-著名的调和级数" aria-label="Permalink to &quot;（11）不要用代码结构来判断时间复杂度，比如：N/1 + N/2 + N/3 + … + N/N，这个流程的时间复杂度是 O(N \\* logN)，著名的调和级数&quot;">​</a></h4><h4 id="_12-时间复杂度只能是对算法流程充分理解才能分析出来-而不是简单的看代码结构-这是一个常见的错误-甚至有些算法的实现用了多层循环嵌套-但时间复杂度是-o-n-的。在【必备】课程里会经常见到" tabindex="-1">（12）时间复杂度只能是对算法流程充分理解才能分析出来，而不是简单的看代码结构！这是一个常见的错误！甚至有些算法的实现用了多层循环嵌套，但时间复杂度是 O(N)的。在【必备】课程里会经常见到 <a class="header-anchor" href="#_12-时间复杂度只能是对算法流程充分理解才能分析出来-而不是简单的看代码结构-这是一个常见的错误-甚至有些算法的实现用了多层循环嵌套-但时间复杂度是-o-n-的。在【必备】课程里会经常见到" aria-label="Permalink to &quot;（12）时间复杂度只能是对算法流程充分理解才能分析出来，而不是简单的看代码结构！这是一个常见的错误！甚至有些算法的实现用了多层循环嵌套，但时间复杂度是 O(N)的。在【必备】课程里会经常见到&quot;">​</a></h4><h4 id="_13-常见复杂度一览" tabindex="-1">（13）常见复杂度一览 <a class="header-anchor" href="#_13-常见复杂度一览" aria-label="Permalink to &quot;（13）常见复杂度一览&quot;">​</a></h4><blockquote><h4 id="o-1-、o-logn-、o-n-、o-n-logn-、o-n-2-o-n-k-、o-2-n-o-k-n-o-n" tabindex="-1">O(1)、O(logN)、O(N)、O(N*logN)、O(N^2) … O(N^k)、O(2^N) … O(k^N) … O(N!) <a class="header-anchor" href="#o-1-、o-logn-、o-n-、o-n-logn-、o-n-2-o-n-k-、o-2-n-o-k-n-o-n" aria-label="Permalink to &quot;O(1)、O(logN)、O(N)、O(N\\*logN)、O(N^2) … O(N^k)、O(2^N) … O(k^N) … O(N!)&quot;">​</a></h4></blockquote><h4 id="_14-时间复杂度非常重要-可以直接判断某个方法能不能通过一个题目-根据数据量猜解法-【必备】课都会讲" tabindex="-1">（14）时间复杂度非常重要，可以直接判断某个方法能不能通过一个题目，根据数据量猜解法，【必备】课都会讲 <a class="header-anchor" href="#_14-时间复杂度非常重要-可以直接判断某个方法能不能通过一个题目-根据数据量猜解法-【必备】课都会讲" aria-label="Permalink to &quot;（14）时间复杂度非常重要，可以直接判断某个方法能不能通过一个题目，根据数据量猜解法，【必备】课都会讲&quot;">​</a></h4><h4 id="_15-整套课会讲很多算法和数据结构-也会见到很多的时间复杂度的表达-持续看课即可" tabindex="-1">（15）整套课会讲很多算法和数据结构，也会见到很多的时间复杂度的表达，持续看课即可 <a class="header-anchor" href="#_15-整套课会讲很多算法和数据结构-也会见到很多的时间复杂度的表达-持续看课即可" aria-label="Permalink to &quot;（15）整套课会讲很多算法和数据结构，也会见到很多的时间复杂度的表达，持续看课即可&quot;">​</a></h4>',24)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
